{
  "story": "Begin with water and carbon dioxide beside a chloroplast under sunlight. Use Next to highlight light capture, then sugar and oxygen. Compare inputs and products: the chloroplast uses light energy to build sugar, storing chemical energy while releasing oxygen.",
  "aha": {
    "stateId": "products",
    "observation": "The chloroplast converts light energy into chemical energy stored in sugar, using carbon dioxide and water and releasing oxygen."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "state-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with explanation and instructions above the experiment. Keep navigation progress on this rail. Brief parameter-control budget: zero. Navigation budget: one index control and Reset.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "photosynthesis-picture",
      "kind": "fixed-picture",
      "presentation": "Arrange inputs, chloroplast, and products left to right, with sunlight above the chloroplast. Keep positions fixed and labels readable at native width. Emphasize only the active region. Assume a healthy green leaf with sufficient sunlight, water, and carbon dioxide. Stages summarize overlapping reactions, not elapsed time. No quantitative measurements are modeled.",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "links": "variant.links"
      }
    },
    {
      "id": "active-location",
      "kind": "active-callout",
      "presentation": "Anchor beside the active region without covering labels. Identify where the highlighted mechanism occurs.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "evidence-status",
      "kind": "value-readout",
      "presentation": "Show one bound status line below the picture. Keep this location fixed across states.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Photosynthesis stage",
      "presentation": "Render Previous and Next with accessible names, visible focus, and keyboard operation. Default index: 0; bounds: 0–2; increment: 1. Changing the index moves the picture highlight and updates the callout and evidence status. Retain Previous and Next names when disabled at boundaries. Every state persists until learner action, including products. Reference captures show products."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore index 0 and the initial highlight, callout, and status. Provide an accessible name, visible focus, and keyboard operation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Photosynthesis in a green leaf",
        "regions": [
          {
            "id": "inputs",
            "label": "Inputs",
            "values": [
              "Carbon dioxide",
              "Water"
            ]
          },
          {
            "id": "sunlight",
            "label": "Sunlight",
            "values": [
              "Light energy"
            ]
          },
          {
            "id": "chloroplast",
            "label": "Chloroplast",
            "phases": [
              "Capture light energy",
              "Build sugar"
            ]
          },
          {
            "id": "products",
            "label": "Products",
            "values": [
              "Sugar",
              "Oxygen"
            ]
          }
        ],
        "links": [
          {
            "from": "inputs",
            "to": "chloroplast",
            "label": "Matter enters"
          },
          {
            "from": "sunlight",
            "to": "chloroplast",
            "label": "Energy enters"
          },
          {
            "from": "chloroplast",
            "to": "products",
            "label": "Matter leaves"
          }
        ],
        "states": [
          {
            "id": "inputs",
            "label": "Starting materials",
            "short": "Inputs",
            "sentence": "Inputs enter the chloroplast.",
            "why": "Carbon dioxide and water supply the matter used in photosynthesis.",
            "active": [
              "inputs"
            ],
            "calloutRegion": "inputs",
            "readouts": [
              {
                "id": "status",
                "label": "Evidence",
                "value": "Matter comes from carbon dioxide and water; energy comes from sunlight."
              }
            ]
          },
          {
            "id": "capture",
            "label": "Capture light",
            "short": "Capture",
            "sentence": "Light capture occurs inside the chloroplast.",
            "why": "Chlorophyll absorbs sunlight, supplying energy that powers sugar formation.",
            "active": [
              "chloroplast"
            ],
            "calloutRegion": "chloroplast",
            "readouts": [
              {
                "id": "status",
                "label": "Evidence",
                "value": "Light supplies energy, not the matter used to build sugar."
              }
            ]
          },
          {
            "id": "products",
            "label": "Sugar stores energy",
            "short": "Products",
            "sentence": "Sugar and oxygen are the products.",
            "why": "Sugar stores captured energy chemically; oxygen is released.",
            "active": [
              "products"
            ],
            "calloutRegion": "products",
            "readouts": [
              {
                "id": "status",
                "label": "Evidence",
                "value": "Carbon dioxide and water become sugar and oxygen; captured light energy is stored chemically in sugar."
              }
            ]
          }
        ]
      }
    ]
  }
}
